class Solution {
public:
    vector<int> maximizeXor(vector<int>& nums, vector<vector<int>>& queries) {
        int n = nums.size();
        int q = queries.size();
        sort(nums.begin(), nums.end());

        vector<int> order(q);
        for (int i = 0; i < q; i++) order[i] = i;
        sort(order.begin(), order.end(), [&](int a, int b) {
            return queries[a][1] < queries[b][1];
        });

        struct Node {
            Node* ch[2];
            Node() { ch[0] = ch[1] = nullptr; }
        };
        Node* root = new Node();

        auto insert = [&](int val) {
            Node* cur = root;
            for (int b = 30; b >= 0; b--) {
                int bit = (val >> b) & 1;
                if (!cur->ch[bit]) cur->ch[bit] = new Node();
                cur = cur->ch[bit];
            }
        };

        auto query = [&](int x) -> int {
            Node* cur = root;
            if (!cur->ch[0] && !cur->ch[1]) return -1;
            int ans = 0;
            for (int b = 30; b >= 0; b--) {
                int bit = (x >> b) & 1;
                int want = 1 - bit;
                if (cur->ch[want]) {
                    ans |= (1 << b);
                    cur = cur->ch[want];
                } else {
                    cur = cur->ch[bit];
                }
            }
            return ans;
        };

        vector<int> result(q);
        int idx = 0;
        for (int i = 0; i < q; i++) {
            int qi = order[i];
            int x = queries[qi][0];
            int m = queries[qi][1];
            while (idx < n && nums[idx] <= m) {
                insert(nums[idx]);
                idx++;
            }
            result[qi] = query(x);
        }

        return result;
    }
};
